mapper.select:
select * from ( select fe.id as event_id, fe.user_id as user_id, coalesce(pu.nickname, pu.username) as user_nickname, pu.avatar as user_avatar, fe.event_type as event_type, fe.target_type as target_type, fe.target_id as target_id, fe.title as title, fe.summary as summary, fe.cover as cover, fe.created_time as created_time from portal_feed_event fe inner join portal_follow pf on pf.following_id = fe.user_id inner join portal_user pu on pu.id = fe.user_id where pf.follower_id = #{userId}
union all
select a.id as event_id, a.author_id as user_id, coalesce(pu.nickname, pu.username) as user_nickname, pu.avatar as user_avatar, 'publish_article' as event_type, 'article' as target_type, a.id as target_id, a.title as title, a.excerpt as summary, a.cover as cover, coalesce(a.update_time, a.create_time) as created_time from portal_article a inner join portal_follow pf on pf.following_id = a.author_id inner join portal_user pu on pu.id = a.author_id where pf.follower_id = #{userId} and a.status = 'published' and not exists ( select 1 from portal_feed_event fe2 where fe2.target_type = 'article' and fe2.target_id = a.id and fe2.user_id = a.author_id ) ) merged order by created_time desc
